            let tracked new_exposed = exposed.tracked_unwrap();
            let tracked block_token = mim_block_opt.tracked_unwrap();
            LL::ghost_insert_block(
                &mut ghost_ll_tracked,
                ptr,
                new_ptr_mem,
                new_raw_mem,
                block_token,
                new_exposed);
            g = (emp_token, Some((delay_token, ghost_ll_tracked)));
